update public.techniques
set nombre_en = 'Python at a glance: colons, indentation and print',
    descripcion_en = 'The minimum to read and write Python without tripping: indented blocks, untyped variables, True and False capitalized and the two divisions.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Indented blocks: after if, for, while or def comes a colon, and the lines inside are shifted 4 spaces.\n```python\nfor i in range(3):\n    print(i)\n```\n```salida\n0\n1\n2\n```","No types and no semicolons: the variable takes the type of the value you give it, and it can change it.\n```python\nx = 5\nx = \"cinco\"\nprint(x)\n```\n```salida\ncinco\n```","True and False are capitalized, and the logical operators are written as words: and, or, not.\n```python\nprint(3 > 2 and not False)\n```\n```salida\nTrue\n```","Two divisions: / always gives a decimal and // gives the whole part.\n```python\nprint(10 / 4, 10 // 4)\n```\n```salida\n2.5 2\n```"]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What does it print?\n```python\nprint(list(range(2, 5)))\n```","opciones":["[2, 3, 4]","[2, 3, 4, 5]","[3, 4]"],"respuesta":"[2, 3, 4]","explicacion":"range(2, 5) starts at 2 and stops before 5."},{"pregunta":"How do you write \"true\" in Python?","opciones":["true","True","TRUE"],"respuesta":"True","explicacion":"In Python booleans are capitalized: True and False."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":0,"titulo":"Python in three rules","cuadros":[{"texto":"A colon and indentation mark each block"},{"texto":"The variable takes the type of the value"},{"texto":"True, False, and, or and not are written like this"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-tecnica-python-chuleta';

update public.techniques
set nombre_en = 'Java at a glance: types, semicolons and braces',
    descripcion_en = 'The minimum to read Java: each variable declares its type, each statement ends with a semicolon and blocks go between braces.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Each statement ends with a semicolon and blocks go between braces.\n```java\nfor (int i = 0; i < 3; i++) {\n    System.out.println(i);\n}\n```\n```salida\n0\n1\n2\n```","Each variable declares its type and can't change it: if it doesn't match, the program won't even compile.\n```java!\nint x = 5;\nx = \"cinco\";\n```\n```salida\ncompilation error\n```","To print you use System.out.println, and to join text, the + sign.\n```java\nString mundo = \"Codia\";\nSystem.out.println(\"Hola, \" + mundo);\n```\n```salida\nHola, Codia\n```","Careful: an int divided by another int drops the decimals. With a decimal in the calculation, the result is a decimal.\n```java\nSystem.out.println(10 / 4);\nSystem.out.println(10 / 4.0);\n```\n```salida\n2\n2.5\n```"]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What does it print?\n```java\nSystem.out.println(9 / 2);\n```","opciones":["4.5","4","5"],"respuesta":"4","explicacion":"9 and 2 are ints: integer division drops the .5."},{"pregunta":"What does each statement end with in Java?","opciones":["A semicolon","A colon","A line break"],"respuesta":"A semicolon","explicacion":"Java requires ; at the end of each statement."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":0,"titulo":"Java in three rules","cuadros":[{"texto":"Each variable declares its type"},{"texto":"Each statement ends with a semicolon"},{"texto":"Blocks go between braces"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-tecnica-java-chuleta';

update public.techniques
set nombre_en = 'JavaScript at a glance: const, === and the surprises of +',
    descripcion_en = 'The minimum to avoid JavaScript''s traps: const and let, always compare with === and watch out when adding text and numbers.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["const for what doesn't change and let for what does. New code doesn't use var.\n```javascript\nconst base = 10;\nlet total = base;\ntotal += 5;\nconsole.log(total);\n```\n```salida\n15\n```","Always compare with ===, which requires the same value and the same type. == converts the types before comparing and gives surprises.\n```javascript\nconsole.log(1 == \"1\", 1 === \"1\");\n```\n```salida\ntrue false\n```","With a text in the mix, + joins instead of adding. To add, convert first with Number.\n```javascript\nconsole.log(\"2\" + 2);\nconsole.log(Number(\"2\") + 2);\n```\n```salida\n22\n4\n```","To print several things, separate them with commas in console.log: they're shown with a space in between.\n```javascript\nconst nombre = \"Ana\";\nconsole.log(\"Hola\", nombre);\n```\n```salida\nHola Ana\n```"]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What does it print?\n```javascript\nconsole.log(\"5\" + 1);\n```","opciones":["6","51","Error"],"respuesta":"51","explicacion":"With a text in the mix, + joins: \"5\" and \"1\" give \"51\"."},{"pregunta":"What does it print?\n```javascript\nconsole.log(2 === 2.0);\n```","opciones":["true","false","Error"],"respuesta":"true","explicacion":"In JavaScript all numbers are the same type: 2 and 2.0 are the same value."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":1,"titulo":"JavaScript in three rules","cuadros":[{"texto":"const by default; let if it's going to change"},{"texto":"Compare with ==="},{"texto":"Text + number joins, it doesn't add"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-tecnica-javascript-chuleta';

update public.techniques
set nombre_en = 'TypeScript at a glance: a colon and the type',
    descripcion_en = 'TypeScript is JavaScript with types: the type goes after the name, with a colon, and if it doesn''t match the program doesn''t compile.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["The type goes after the name, with a colon.\n```typescript\nlet edad: number = 15;\nconsole.log(edad + 1);\n```\n```salida\n16\n```","If the value doesn't match the type, it doesn't compile: the error shows up before running.\n```typescript!\nlet edad: number = \"quince\";\n```\n```salida\ncompilation error\n```","Functions declare the type of each parameter and of the result.\n```typescript\nfunction area(base: number, altura: number): number {\n  return (base * altura) / 2;\n}\nconsole.log(area(6, 4));\n```\n```salida\n12\n```","Everything else is JavaScript: const, let, ===, arrays and objects work the same.\n```typescript\nconst xs: number[] = [1, 2, 3];\nconsole.log(xs.length === 3);\n```\n```salida\ntrue\n```"]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What happens with this code?\n```typescript\nfunction f(n: number): number {\n  return n;\n}\nf(\"1\");\n```","opciones":["It doesn't compile: compilation error","It returns 1","It returns \"1\""],"respuesta":"It doesn't compile: compilation error","explicacion":"f asks for a number and gets a string: the compiler rejects it."},{"pregunta":"Where is the type of a variable written in TypeScript?","opciones":["After the name, with a colon","Before the name, as in Java","In a comment"],"respuesta":"After the name, with a colon","explicacion":"For example: let edad: number = 15."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":0,"titulo":"TypeScript in three rules","cuadros":[{"texto":"name: type"},{"texto":"If the type doesn't match, it doesn't compile"},{"texto":"The rest is JavaScript"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-tecnica-typescript-chuleta';

update public.techniques
set nombre_en = 'Four languages, four worlds: what each one is for',
    descripcion_en = 'The ideas of The basics are the same in every language; what changes is how they''re written and what they''re used for. Compiled or interpreted, static or dynamic typing, and the place of Python, Java, JavaScript and TypeScript.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["You already know the basics: variables, conditionals, loops, functions and data structures. Those ideas are the same in every language. What changes is how they're written, how they run and what each one is used for.","Interpreted or compiled. Python and JavaScript run with an interpreter, which reads the program and runs it as it goes. Java is first compiled to bytecode, which then runs on the Java virtual machine (JVM). TypeScript is compiled to JavaScript, checking the types along the way.","Dynamic or static typing. In Python and JavaScript the value carries the type and type errors show up when running. In Java and TypeScript you declare the types and the compiler warns you earlier. Look at what happens when you join a text with a number. Python refuses:\n```python!\nprint(\"Edad: \" + 15)\n```\n```salida\nTypeError\n```\nJava, JavaScript and TypeScript turn the number into text:\n```java\nSystem.out.println(\"Edad: \" + 15);\n```\n```javascript\nconsole.log(\"Edad: \" + 15);\n```\n```typescript\nconsole.log(\"Edad: \" + 15);\n```\n```salida\nEdad: 15\n```","What each one is used for. Python: data science, artificial intelligence, automating tasks and teaching programming. Java: Android apps, systems at banks and big companies, servers. JavaScript: everything that moves on a web page, and also servers with Node.js. TypeScript: JavaScript with types, for big web projects built by teams (Prodigia is written in TypeScript).","The classic first program, in all four:\n```python\nprint(\"Hola, mundo\")\n```\n```java\nSystem.out.println(\"Hola, mundo\");\n```\n```javascript\nconsole.log(\"Hola, mundo\");\n```\n```typescript\nconsole.log(\"Hola, mundo\");\n```\n```salida\nHola, mundo\n```","There's no \"best\" language: there are tools for different jobs. What you learned in The basics carries over: someone who understands a loop in Python understands it in Java in minutes. In the next sections you'll see each language from the inside and what it's used for."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Which language do all browsers understand directly?","opciones":["Python","JavaScript","Java"],"respuesta":"JavaScript","explicacion":"JavaScript is the language of web pages; TypeScript is compiled to JavaScript to run there."},{"pregunta":"What happens when you run this in Python?\n```python\nprint(\"Puntos: \" + 10)\n```","opciones":["It prints Puntos: 10","It fails with TypeError","It prints Puntos: 10.0"],"respuesta":"It fails with TypeError","explicacion":"Python doesn't join text with numbers on its own: you have to convert with str(10)."},{"pregunta":"What does the TypeScript compiler do before running?","opciones":["Checks the types and turns it into JavaScript","Turns it into Python","Runs it on the JVM"],"respuesta":"Checks the types and turns it into JavaScript","explicacion":"Types are checked when compiling and disappear in the JavaScript that runs."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":1,"titulo":"How does it run?","cuadros":[{"texto":"Python: an interpreter reads it and runs it"},{"texto":"JavaScript: the browser or Node.js runs it"},{"texto":"Java: it's compiled to bytecode and the JVM runs it"},{"texto":"TypeScript: it's checked, compiled to JavaScript and runs as JavaScript"}]},{"tipo":"cuadros","despuesDePaso":3,"titulo":"What is it used for?","cuadros":[{"texto":"Python: data and artificial intelligence"},{"texto":"Java: Android and companies"},{"texto":"JavaScript: the web"},{"texto":"TypeScript: big web projects"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-clase-lenguajes-panorama';

update public.techniques
set nombre_en = 'Python 1: a language that reads almost like English',
    descripcion_en = 'Indented blocks, f-strings, lists and loops, the three division operations and list comprehensions.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Python was designed to be easy to read. It uses no semicolons or braces: blocks are marked with a colon and an indentation of 4 spaces.\n```python\nedad = 16\nif edad >= 18:\n    print(\"Puede votar\")\nelse:\n    print(\"Todavía no\")\nprint(\"Fin\")\n```\n```salida\nTodavía no\nFin\n```","Indentation isn't decoration: if it's missing, the program won't even start.\n```python!\nif True:\nprint(\"hola\")\n```\n```salida\nIndentationError\n```","f-strings put variables inside text with braces, and print separates with a space whatever you pass it with commas.\n```python\nnombre = \"Ana\"\npuntos = 120\nprint(f\"{nombre} tiene {puntos} puntos\")\nprint(nombre, puntos)\n```\n```salida\nAna tiene 120 puntos\nAna 120\n```","Lists and the for loop, which goes directly through the elements. sum and len give you the average in one line.\n```python\nnotas = [7, 9, 6]\nfor n in notas:\n    print(n * 2)\nprint(sum(notas) / len(notas))\n```\n```salida\n14\n18\n12\n7.333333333333333\n```","Three operations that confuse people at first: / always gives a decimal, // is integer division and ** is the power.\n```python\nprint(7 / 2)\nprint(7 // 2)\nprint(2 ** 10)\n```\n```salida\n3.5\n3\n1024\n```","List comprehensions build a new list in a single line: \"x times x, for each x from 1 to 5\".\n```python\ncuadrados = [x * x for x in range(1, 6)]\nprint(cuadrados)\n```\n```salida\n[1, 4, 9, 16, 25]\n```"]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What does it print?\n```python\nprint(9 // 2, 9 / 2)\n```","opciones":["4 4.5","4.5 4.5","4 4"],"respuesta":"4 4.5","explicacion":"// is integer division (4) and / always gives a decimal (4.5)."},{"pregunta":"How does Python mark where a block starts and ends?","opciones":["With braces","With indentation","With semicolons"],"respuesta":"With indentation","explicacion":"A colon at the end of the line and the lines inside shifted 4 spaces."},{"pregunta":"What does it print?\n```python\nprint([x * 2 for x in [1, 2, 3]])\n```","opciones":["[2, 4, 6]","[1, 2, 3, 1, 2, 3]","[2, 4, 6, 2]"],"respuesta":"[2, 4, 6]","explicacion":"The comprehension multiplies each element by 2."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":0,"titulo":"What's special about Python","cuadros":[{"texto":"Blocks with a colon and indentation"},{"texto":"f-strings: f\"{variable}\""},{"texto":"/ decimal, // integer, ** power"},{"texto":"Comprehensions: [x * x for x in lista]"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-clase-python-1-sintaxis';

update public.techniques
set nombre_en = 'Python 2: dictionaries, functions and modules',
    descripcion_en = 'Storing data by name with dictionaries, writing functions with default values, importing modules and avoiding KeyError.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["A dictionary stores key-value pairs: you look things up by name instead of by position.\n```python\nalumno = {\"nombre\": \"Luis\", \"edad\": 15}\nalumno[\"edad\"] = 16\nprint(alumno[\"nombre\"], alumno[\"edad\"])\nprint(len(alumno))\n```\n```salida\nLuis 16\n2\n```","To go through it, items() gives each key with its value (in the order they were added).\n```python\nprecios = {\"pan\": 2, \"leche\": 3}\nfor producto, precio in precios.items():\n    print(producto, precio)\n```\n```salida\npan 2\nleche 3\n```","Functions are defined with def. A parameter can have a default value, which is used if you don't pass it.\n```python\ndef saludar(nombre, saludo=\"Hola\"):\n    return f\"{saludo}, {nombre}\"\n\nprint(saludar(\"Ana\"))\nprint(saludar(\"Ana\", \"Buenas\"))\n```\n```salida\nHola, Ana\nBuenas, Ana\n```","Python comes with many ready-made modules. With import you use them: math has square roots, pi and much more.\n```python\nimport math\nprint(math.sqrt(81))\nprint(math.pi > 3)\n```\n```salida\n9.0\nTrue\n```","The typical dictionary error: asking for a key that doesn't exist.\n```python!\nedades = {\"Ana\": 15}\nprint(edades[\"Luis\"])\n```\n```salida\nKeyError\n```\nWith get you ask for the key and give a value in case it's not there:\n```python\nedades = {\"Ana\": 15}\nprint(edades.get(\"Luis\", 0))\n```\n```salida\n0\n```"]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What does it print?\n```python\nd = {\"a\": 1, \"b\": 2}\nd[\"a\"] = 5\nprint(d[\"a\"] + d[\"b\"])\n```","opciones":["7","3","6"],"respuesta":"7","explicacion":"d[\"a\"] becomes 5, and 5 + 2 = 7."},{"pregunta":"What happens when you run this?\n```python\nprint({\"x\": 1}[\"y\"])\n```","opciones":["It prints None","It fails with KeyError","It prints 0"],"respuesta":"It fails with KeyError","explicacion":"The key \"y\" doesn't exist. With .get(\"y\") it would return None without failing."},{"pregunta":"What is import for in Python?","opciones":["To use code from another module, like math","To create a variable","To print on the screen"],"respuesta":"To use code from another module, like math","explicacion":"import math brings in the functions of the math module (sqrt, pi, etc.)."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":0,"titulo":"Dictionaries in Python","cuadros":[{"texto":"d[\"clave\"] = valor stores or changes"},{"texto":"for k, v in d.items() goes through it"},{"texto":"d.get(\"clave\", 0) doesn't fail if it's missing"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-clase-python-2-diccionarios-y-funciones';

update public.techniques
set nombre_en = 'Python 3: where it''s used — data, automation and artificial intelligence',
    descripcion_en = 'Why Python is the language of data and AI, with small examples of analysis, sorting and word counting, and what its weak point is.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Python dominates in data science and artificial intelligence (with libraries like NumPy, pandas, scikit-learn and PyTorch), in automating tasks (renaming files, reading spreadsheets, downloading data), in web servers (Django and Flask) and in teaching.","A small data analysis, without any library: maximum, minimum and average.\n```python\ntemperaturas = [21, 25, 19, 30, 24]\nprint(\"Máxima:\", max(temperaturas))\nprint(\"Mínima:\", min(temperaturas))\nprint(\"Promedio:\", sum(temperaturas) / len(temperaturas))\n```\n```salida\nMáxima: 30\nMínima: 19\nPromedio: 23.8\n```","Automating means sorting and cleaning data in a few lines: here, capitalizing the first letter and sorting alphabetically.\n```python\nnombres = [\"sofía\", \"ana\", \"Luis\", \"bruno\"]\nordenados = sorted(n.capitalize() for n in nombres)\nprint(ordenados)\n```\n```salida\n['Ana', 'Bruno', 'Luis', 'Sofía']\n```","Counting words is the basis of text analysis (and of how many language models get started).\n```python\ntexto = \"el gato y el perro y el pez\"\nconteo = {}\nfor palabra in texto.split():\n    conteo[palabra] = conteo.get(palabra, 0) + 1\nprint(conteo[\"el\"], conteo[\"y\"])\n```\n```salida\n3 2\n```","Why Python won in AI: the syntax is short, there are thousands of libraries and the scientific community adopted it. Its weak point is speed: for heavy calculations it's slower than Java, which is why the big libraries are written in C on the inside and Python only \"directs\" them."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What does it print?\n```python\nprint(max([3, 8, 2]) - min([3, 8, 2]))\n```","opciones":["6","8","11"],"respuesta":"6","explicacion":"The maximum is 8 and the minimum 2: 8 − 2 = 6."},{"pregunta":"In which area is Python used the most?","opciones":["iPhone apps","Data science and artificial intelligence","Animating web pages in the browser"],"respuesta":"Data science and artificial intelligence","explicacion":"Libraries like NumPy, pandas and PyTorch made it the standard in data and AI."},{"pregunta":"What does it print?\n```python\npalabras = \"a b a\".split()\nprint(palabras.count(\"a\"))\n```","opciones":["1","2","3"],"respuesta":"2","explicacion":"split separates by spaces: [\"a\", \"b\", \"a\"], and \"a\" appears 2 times."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":0,"titulo":"Python in the real world","cuadros":[{"texto":"Data and AI: NumPy, pandas, PyTorch"},{"texto":"Automating: files, spreadsheets, downloads"},{"texto":"Web: Django and Flask"},{"texto":"Weak point: speed"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-clase-python-3-usos';

update public.techniques
set nombre_en = 'Java 1: declared types and everything inside a class',
    descripcion_en = 'What a Java program looks like, why it''s compiled, the basic types, static methods, arrays and integer division.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["A complete Java program is a class with a main method: public class Main, and inside it public static void main(String[] args). In these lessons we only show what goes inside main. Java is compiled: javac checks the whole program and turns it into bytecode, which the Java virtual machine (JVM) then runs. That's why people say \"write once, run anywhere\".","Each variable declares its type: int (integer), double (decimal), String (text) and boolean (true or false).\n```java\nint edad = 16;\ndouble altura = 1.68;\nString nombre = \"Luis\";\nboolean estudia = true;\nSystem.out.println(nombre + \" tiene \" + edad);\nSystem.out.println(altura * 2);\nSystem.out.println(estudia);\n```\n```salida\nLuis tiene 16\n3.36\ntrue\n```","The compiler catches type errors before anything runs:\n```java!\nint edad = \"dieciseis\";\n```\n```salida\ncompilation error\n```","Functions in Java are called methods and they also declare types: the one of the result and the one of each parameter.\n```java\nstatic int doble(int n) {\n    return n * 2;\n}\nSystem.out.println(doble(21));\n```\n```salida\n42\n```","Arrays have a fixed size, and Java's for has a short form to go through them.\n```java\nint[] notas = {7, 9, 6};\nint suma = 0;\nfor (int n : notas) {\n    suma += n;\n}\nSystem.out.println(suma);\nSystem.out.println(suma / notas.length);\n```\n```salida\n22\n7\n```","Careful with division: between two ints, Java drops the decimals. With a double in the calculation, the result is a decimal.\n```java\nSystem.out.println(7 / 2);\nSystem.out.println(7 / 2.0);\n```\n```salida\n3\n3.5\n```"]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What does it print?\n```java\nSystem.out.println(10 / 4);\n```","opciones":["2.5","2","3"],"respuesta":"2","explicacion":"10 and 4 are ints: integer division gives 2."},{"pregunta":"What happens with this code?\n```java\nString s = 5;\n```","opciones":["It prints 5","It doesn't compile: compilation error","It stores null"],"respuesta":"It doesn't compile: compilation error","explicacion":"An int can't be stored in a String variable."},{"pregunta":"What runs Java programs once they're compiled?","opciones":["The browser","The Java virtual machine (JVM)","The Python interpreter"],"respuesta":"The Java virtual machine (JVM)","explicacion":"javac generates bytecode and the JVM runs it."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":0,"titulo":"How Java runs","cuadros":[{"texto":"You write Main.java"},{"texto":"javac checks it and compiles it to bytecode"},{"texto":"The JVM runs the bytecode on any system"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-clase-java-1-estructura';

update public.techniques
set nombre_en = 'Java 2: classes and objects',
    descripcion_en = 'Java''s central idea: a class is a mold and an object is something concrete made with that mold. Constructors, methods, ArrayList and a runtime error.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Java is an object-oriented language. A class is a mold: it says what data (attributes) and what actions (methods) something has. An object is a concrete thing made with that mold, with its own data.","A Mascota (pet) class with a constructor (the method that builds the object) and a method. With new an object is created.\n```java\nstatic class Mascota {\n    String nombre;\n    int edad;\n\n    Mascota(String nombre, int edad) {\n        this.nombre = nombre;\n        this.edad = edad;\n    }\n\n    String presentarse() {\n        return nombre + \" tiene \" + edad;\n    }\n}\nMascota m = new Mascota(\"Toby\", 3);\nSystem.out.println(m.presentarse());\n```\n```salida\nToby tiene 3\n```","Each object keeps its own data: adding to one doesn't change the other.\n```java\nstatic class Contador {\n    int valor = 0;\n\n    void sumar() {\n        valor++;\n    }\n}\nContador a = new Contador();\nContador b = new Contador();\na.sumar();\na.sumar();\nb.sumar();\nSystem.out.println(a.valor + \" \" + b.valor);\n```\n```salida\n2 1\n```","For lists that grow you use ArrayList, which has to be imported. Between the < > signs goes the type of what it stores.\n```java\nimport java.util.ArrayList;\nArrayList<String> nombres = new ArrayList<>();\nnombres.add(\"Ana\");\nnombres.add(\"Luis\");\nnombres.add(\"Bea\");\nSystem.out.println(nombres.size());\nSystem.out.println(nombres.get(1));\nSystem.out.println(nombres);\n```\n```salida\n3\nLuis\n[Ana, Luis, Bea]\n```","There are errors the compiler can't see, because they depend on the data: they show up when running.\n```java!\nint[] a = {1, 2, 3};\nSystem.out.println(a[3]);\n```\n```salida\nArrayIndexOutOfBoundsException\n```"]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What does it print?\n```java\nstatic class Caja {\n    int n;\n\n    Caja(int n) {\n        this.n = n;\n    }\n}\nCaja c = new Caja(5);\nc.n = c.n + 2;\nSystem.out.println(c.n);\n```","opciones":["5","7","2"],"respuesta":"7","explicacion":"The object starts with n = 5 and then 2 is added."},{"pregunta":"What is an object in Java?","opciones":["A type of loop","A concrete thing created with the mold of a class","A .java file"],"respuesta":"A concrete thing created with the mold of a class","explicacion":"The class is the mold; with new, objects are created from it."},{"pregunta":"What does it print?\n```java\nimport java.util.ArrayList;\nArrayList<Integer> xs = new ArrayList<>();\nxs.add(4);\nxs.add(8);\nSystem.out.println(xs.size() + xs.get(0));\n```","opciones":["6","12","24"],"respuesta":"6","explicacion":"size() is 2 and get(0) is 4: 2 + 4 = 6."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":1,"titulo":"Class and object","cuadros":[{"texto":"Class: the mold (Mascota)"},{"texto":"Object: something concrete (Toby, 3 years old)"},{"texto":"new creates the object; the constructor fills it in"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-clase-java-2-objetos';

update public.techniques
set nombre_en = 'Java 3: where it''s used — Android, companies and servers',
    descripcion_en = 'Why banks, companies and Android trust Java, with a bank account example, an inventory HashMap and the price of its safety: writing more.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Java was born in 1995 with the promise of \"write once, run anywhere\": the same bytecode runs on Windows, Mac, Linux or a phone. Today it's in Android apps (along with Kotlin), in the systems of banks and big companies, in servers (with Spring) and in video games like the Java edition of Minecraft.","Why companies choose it: strict types and the compiler catch many errors before the system reaches users, the JVM is very fast, and organizing everything in classes helps hundreds of people work on the same code.","A typical company example: a bank account. The balance (saldo) is private (only the class itself touches it) and it's changed with methods that enforce the rules, like not withdrawing more than there is.\n```java\nstatic class Cuenta {\n    private int saldo = 0;\n\n    void depositar(int monto) {\n        saldo += monto;\n    }\n\n    boolean retirar(int monto) {\n        if (monto > saldo) {\n            return false;\n        }\n        saldo -= monto;\n        return true;\n    }\n\n    int getSaldo() {\n        return saldo;\n    }\n}\nCuenta c = new Cuenta();\nc.depositar(100);\nSystem.out.println(c.retirar(30));\nSystem.out.println(c.retirar(500));\nSystem.out.println(c.getSaldo());\n```\n```salida\ntrue\nfalse\n70\n```","An inventory with HashMap, Java's dictionary: it stores key-value pairs.\n```java\nimport java.util.HashMap;\nHashMap<String, Integer> stock = new HashMap<>();\nstock.put(\"lapiz\", 10);\nstock.put(\"cuaderno\", 4);\nstock.put(\"lapiz\", stock.get(\"lapiz\") - 3);\nSystem.out.println(stock.get(\"lapiz\"));\nSystem.out.println(stock.containsKey(\"goma\"));\n```\n```salida\n7\nfalse\n```","The price of that safety: Java asks you to write more. What in Python is one print line, in Java goes inside a class and a main, with the type of everything declared:\n```java\nString saludo = \"hola\";\nSystem.out.println(saludo);\n```\n```salida\nhola\n```\nYou write more, but the compiler protects you more: that's why it shines in big systems that have to work for years."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What does it print?\n```java\nint saldo = 50;\nint retiro = 80;\nif (retiro > saldo) {\n    System.out.println(\"Fondos insuficientes\");\n} else {\n    saldo -= retiro;\n    System.out.println(saldo);\n}\n```","opciones":["-30","Fondos insuficientes","50"],"respuesta":"Fondos insuficientes","explicacion":"80 is greater than 50, so it goes into the if and doesn't subtract anything."},{"pregunta":"What is Java used for a lot?","opciones":["Android apps and company systems","Only web pages in the browser","Spreadsheets"],"respuesta":"Android apps and company systems","explicacion":"Android, banks, companies and servers are its main ground."},{"pregunta":"What does it mean for an attribute to be private?","opciones":["That it's constant","That only the code of its own class can use it","That it's deleted when the program ends"],"respuesta":"That only the code of its own class can use it","explicacion":"That way nobody changes the balance without going through the rules of depositing and withdrawing."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":0,"titulo":"Java in the real world","cuadros":[{"texto":"Android apps"},{"texto":"Banks and companies"},{"texto":"Servers with Spring"},{"texto":"Minecraft (Java edition)"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-clase-java-3-usos';

update public.techniques
set nombre_en = 'JavaScript 1: the language of the web',
    descripcion_en = 'Why JavaScript is on every page, const and let, == versus ===, array methods and what its numbers are like.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["JavaScript is the only language that every browser understands: every button that reacts, every menu that opens and every animation on a page uses it. Outside the browser it runs with Node.js.","const for what doesn't change and let for what does. A const can't be reassigned:\n```javascript\nconst nombre = \"Ana\";\nlet puntos = 10;\npuntos = puntos + 5;\nconsole.log(nombre + \" tiene \" + puntos);\n```\n```salida\nAna tiene 15\n```\n```javascript!\nconst vidas = 3;\nvidas = 2;\n```\n```salida\nTypeError\n```","== compares by converting types and gives surprises; === requires the same value and the same type. Always use ===.\n```javascript\nconsole.log(5 == \"5\");\nconsole.log(5 === \"5\");\nconsole.log(0 == false);\n```\n```salida\ntrue\nfalse\ntrue\n```","Arrays come with very common methods: map transforms each element, filter keeps some of them and join puts them together in a text.\n```javascript\nconst notas = [7, 9, 6];\nconst dobles = notas.map((n) => n * 2);\nconst aprobadas = notas.filter((n) => n >= 7);\nconsole.log(dobles.join(\", \"));\nconsole.log(aprobadas.length);\n```\n```salida\n14, 18, 12\n2\n```","All numbers are the same type (there are no separate integers): 7 / 2 gives 3.5 and, for the whole part, you use Math.floor. Decimals are stored in binary, which is why leftovers show up, as in 0.1 + 0.2.\n```javascript\nconsole.log(7 / 2);\nconsole.log(Math.floor(7 / 2));\nconsole.log(0.1 + 0.2);\n```\n```salida\n3.5\n3\n0.30000000000000004\n```"]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What does it print?\n```javascript\nconsole.log(\"3\" + 4);\n```","opciones":["7","34","Error"],"respuesta":"34","explicacion":"With a text in the mix, + joins: \"3\" and \"4\" give \"34\"."},{"pregunta":"What does it print?\n```javascript\nconsole.log([1, 2, 3].map((x) => x * x).join(\"-\"));\n```","opciones":["1-4-9","1-2-3","2-4-6"],"respuesta":"1-4-9","explicacion":"map squares each number and join puts them together with dashes."},{"pregunta":"What's the difference between == and ===?","opciones":["None","=== also compares the type","== is stricter"],"respuesta":"=== also compares the type","explicacion":"5 == \"5\" gives true because it converts; 5 === \"5\" gives false."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":1,"titulo":"JavaScript on the web","cuadros":[{"texto":"The browser runs it on every page"},{"texto":"const and let declare variables"},{"texto":"Use === to compare"},{"texto":"map, filter and join for arrays"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-clase-javascript-1-sintaxis';

update public.techniques
set nombre_en = 'JavaScript 2: objects, arrow functions and JSON',
    descripcion_en = 'Objects with properties, regular and arrow functions, destructuring, JSON (the data format of the web) and the famous undefined.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["An object groups named data, like a Python dictionary.\n```javascript\nconst alumno = { nombre: \"Luis\", edad: 15 };\nalumno.edad = 16;\nconsole.log(alumno.nombre, alumno.edad);\nconsole.log(Object.keys(alumno).length);\n```\n```salida\nLuis 16\n2\n```","There are two ways to write functions: the regular one and the shorter arrow one.\n```javascript\nfunction sumar(a, b) {\n  return a + b;\n}\nconst restar = (a, b) => a - b;\nconsole.log(sumar(5, 3), restar(5, 3));\n```\n```salida\n8 2\n```","Destructuring pulls properties out into variables, and the three dots copy one array into another.\n```javascript\nconst punto = { x: 3, y: 4 };\nconst { x, y } = punto;\nconsole.log(x * y);\nconst lista = [1, 2];\nconst mas = [...lista, 3];\nconsole.log(mas.length);\n```\n```salida\n12\n3\n```","JSON is the format data travels in across the internet. JSON.stringify turns an object into text and JSON.parse does the opposite.\n```javascript\nconst datos = { mundo: \"Codia\", nivel: 4 };\nconst texto = JSON.stringify(datos);\nconsole.log(texto);\nconst otra = JSON.parse(texto);\nconsole.log(otra.nivel + 1);\n```\n```salida\n{\"mundo\":\"Codia\",\"nivel\":4}\n5\n```","Asking for a property that doesn't exist doesn't fail: it gives undefined.\n```javascript\nconst o = { a: 1 };\nconsole.log(o.b);\n```\n```salida\nundefined\n```\nBut asking undefined for something does fail, and it's one of the most common errors on the web:\n```javascript!\nconst o = { a: 1 };\nconsole.log(o.b.c);\n```\n```salida\nTypeError\n```"]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What does it print?\n```javascript\nconst p = { a: 2, b: 3 };\nconsole.log(p.a * p.b);\n```","opciones":["5","6","23"],"respuesta":"6","explicacion":"p.a is 2 and p.b is 3: 2 × 3 = 6."},{"pregunta":"What does it print?\n```javascript\nconsole.log(JSON.stringify({ x: 1 }));\n```","opciones":["{\"x\":1}","{ x: 1 }","x:1"],"respuesta":"{\"x\":1}","explicacion":"JSON puts the keys in double quotes and leaves no spaces."},{"pregunta":"What happens when you run this?\n```javascript\nconst u = undefined;\nconsole.log(u.largo);\n```","opciones":["It prints undefined","It fails with TypeError","It prints 0"],"respuesta":"It fails with TypeError","explicacion":"You can't read a property of undefined."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":3,"titulo":"A piece of data that travels across the internet","cuadros":[{"texto":"An object in the browser"},{"texto":"JSON.stringify: turns it into text"},{"texto":"It travels to the server"},{"texto":"JSON.parse: it becomes an object again"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-clase-javascript-2-objetos-y-funciones';

update public.techniques
set nombre_en = 'JavaScript 3: where it''s used — web pages, servers and apps',
    descripcion_en = 'From the browser to servers and phones: React, Node.js, React Native and Electron, the idea of a callback and why so much flexibility calls for care.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["In the browser, JavaScript changes the page when you do something: a click, typing, scrolling. Big pages use frameworks like React, Vue or Angular. Prodigia, for example, is built with React.","Outside the browser it's everywhere: servers with Node.js, phone apps with React Native (like Prodigia's Android app) and desktop programs with Electron (like the VS Code editor).","The web works with the idea of \"when this happens, do that\": you pass a function to another one so it calls it at the right moment. That function is called a callback.\n```javascript\nfunction alHacerClic(accion) {\n  console.log(\"Clic recibido\");\n  accion();\n}\nalHacerClic(() => console.log(\"Abriendo el panel\"));\n```\n```salida\nClic recibido\nAbriendo el panel\n```","A shopping cart, typical of an online store: reduce goes through the list adding up the total.\n```javascript\nconst carrito = [\n  { producto: \"lapiz\", precio: 2 },\n  { producto: \"cuaderno\", precio: 5 },\n];\nconst total = carrito.reduce((suma, item) => suma + item.precio, 0);\nconsole.log(\"Total: \" + total);\n```\n```salida\nTotal: 7\n```","Advantage and caution: JavaScript is everywhere and is very flexible, but that flexibility brings surprises that give no warning:\n```javascript\nconsole.log(\"3\" + 4);\nconsole.log(1 == \"1\");\n```\n```salida\n34\ntrue\n```\nThat's why big projects usually move to TypeScript, which adds types."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Where does JavaScript run, besides the browser?","opciones":["Only in the browser","On servers, with Node.js","On the JVM"],"respuesta":"On servers, with Node.js","explicacion":"Node.js lets you use JavaScript outside the browser."},{"pregunta":"What does it print?\n```javascript\nconsole.log([2, 3, 4].reduce((a, b) => a + b, 0));\n```","opciones":["9","24","234"],"respuesta":"9","explicacion":"reduce adds everything starting at 0: 2 + 3 + 4 = 9."},{"pregunta":"What is a callback?","opciones":["A JavaScript error","A function passed to another one so it calls it later","A constant variable"],"respuesta":"A function passed to another one so it calls it later","explicacion":"It's the basis of \"when this happens, do that\" on the web."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":0,"titulo":"JavaScript in the real world","cuadros":[{"texto":"Web pages: React, Vue, Angular"},{"texto":"Servers: Node.js"},{"texto":"Phone apps: React Native"},{"texto":"Desktop: Electron"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-clase-javascript-3-usos';

update public.techniques
set nombre_en = 'TypeScript 1: JavaScript with types',
    descripcion_en = 'What TypeScript adds to JavaScript: type annotations, errors before running, inference and typed functions.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["TypeScript is JavaScript with types. The compiler checks that each value is of the expected type and then generates normal JavaScript: the types disappear when running. Almost any valid JavaScript program is valid TypeScript.","Annotations go after the name, with a colon:\n```typescript\nlet nombre: string = \"Ana\";\nlet edad: number = 15;\nlet activo: boolean = true;\nconsole.log(nombre, edad + 1, activo);\n```\n```salida\nAna 16 true\n```","What in JavaScript would be an error when running (or a silent error), here doesn't even compile:\n```typescript!\nlet puntos: number = 10;\npuntos = \"diez\";\n```\n```salida\ncompilation error\n```","You don't have to write every type: TypeScript deduces them (inference). It knows precios is a list of numbers and won't let you put text in it.\n```typescript\nconst precios = [3, 5, 2];\nconst total = precios.reduce((a, b) => a + b, 0);\nconsole.log(total.toFixed(2));\n```\n```salida\n10.00\n```\n```typescript!\nconst precios = [3, 5, 2];\nprecios.push(\"gratis\");\n```\n```salida\ncompilation error\n```","Functions declare the type of their parameters and of their result, and whoever calls them wrong finds out before running.\n```typescript\nfunction promedio(notas: number[]): number {\n  return notas.reduce((a, b) => a + b, 0) / notas.length;\n}\nconsole.log(promedio([6, 8, 10]));\n```\n```salida\n8\n```\n```typescript!\nfunction doble(n: number): number {\n  return n * 2;\n}\ndoble(\"4\");\n```\n```salida\ncompilation error\n```"]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What happens with this code?\n```typescript\nlet x: string = 5;\n```","opciones":["It stores \"5\"","It doesn't compile: compilation error","It stores 5"],"respuesta":"It doesn't compile: compilation error","explicacion":"x is a string and 5 is a number: the compiler rejects it."},{"pregunta":"What's left of the types when the program runs?","opciones":["Nothing: they're erased when compiling to JavaScript","They're checked again on every line","They're saved in a separate file"],"respuesta":"Nothing: they're erased when compiling to JavaScript","explicacion":"Types only exist for the compiler; what runs is JavaScript."},{"pregunta":"What does it print?\n```typescript\nconst n: number = 7;\nconsole.log(n * 3);\n```","opciones":["21","73","777"],"respuesta":"21","explicacion":"n is a number: 7 × 3 = 21."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":0,"titulo":"How TypeScript runs","cuadros":[{"texto":"You write code with types"},{"texto":"tsc checks the types"},{"texto":"It generates JavaScript without types"},{"texto":"It runs like any JavaScript"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-clase-typescript-1-tipos';

update public.techniques
set nombre_en = 'TypeScript 2: interfaces, unions and null',
    descripcion_en = 'Describing the shape of an object with interface, limiting values with union types and handling what can be null with care.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["An interface describes the shape an object must have. A question mark marks an optional property.\n```typescript\ninterface Jugador {\n  nombre: string;\n  nivel: number;\n  clan?: string;\n}\nconst j: Jugador = { nombre: \"Bea\", nivel: 7 };\nconsole.log(j.nombre, j.nivel);\nconsole.log(j.clan === undefined);\n```\n```salida\nBea 7\ntrue\n```","If a required property is missing, it doesn't compile:\n```typescript!\ninterface Jugador {\n  nombre: string;\n  nivel: number;\n}\nconst j: Jugador = { nombre: \"Bea\" };\n```\n```salida\ncompilation error\n```","A union type limits the possible values. That way, a rank can only be one of the ones that exist:\n```typescript\ntype Rango = \"bronce\" | \"plata\" | \"oro\";\nfunction siguiente(r: Rango): Rango {\n  if (r === \"bronce\") return \"plata\";\n  return \"oro\";\n}\nconsole.log(siguiente(\"bronce\"));\n```\n```salida\nplata\n```\n```typescript!\ntype Rango = \"bronce\" | \"plata\" | \"oro\";\nconst r: Rango = \"diamante\";\n```\n```salida\ncompilation error\n```","If something can be missing, you write it with | null, and the compiler makes you check it before using it.\n```typescript\nfunction largo(texto: string | null): number {\n  if (texto === null) {\n    return 0;\n  }\n  return texto.length;\n}\nconsole.log(largo(\"hola\"), largo(null));\n```\n```salida\n4 0\n```","Why it matters: in JavaScript, forgetting that something can be null or undefined is one of the most common causes of errors on web pages. TypeScript turns that oversight into an editor warning before it reaches users."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What happens with this code?\n```typescript\ninterface P {\n  x: number;\n}\nconst p: P = { x: \"1\" };\n```","opciones":["It compiles and x is \"1\"","It doesn't compile: compilation error","It compiles and x is 1"],"respuesta":"It doesn't compile: compilation error","explicacion":"x has to be a number and it's given a string."},{"pregunta":"What does it print?\n```typescript\ntype Color = \"rojo\" | \"azul\";\nconst c: Color = \"azul\";\nconsole.log(c.toUpperCase());\n```","opciones":["azul","AZUL","Azul"],"respuesta":"AZUL","explicacion":"c is a text: toUpperCase makes it uppercase."},{"pregunta":"What is an interface for?","opciones":["To draw a page's interface","To describe the shape an object must have","To import modules"],"respuesta":"To describe the shape an object must have","explicacion":"It says which properties it has and what type each one is."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":0,"titulo":"TypeScript tools","cuadros":[{"texto":"interface: the shape of an object"},{"texto":"prop?: optional property"},{"texto":"\"a\" | \"b\": only those values"},{"texto":"| null: it can be missing, you have to check it"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-clase-typescript-2-interfaces';

update public.techniques
set nombre_en = 'TypeScript 3: where it''s used — big projects and teams',
    descripcion_en = 'Where TypeScript is used, how it helps a team, a realistic example with the data of a game, generics and when plain JavaScript is enough.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["TypeScript is used wherever JavaScript would be, but in big projects: pages with React, Angular or Vue, servers with Node.js and phone apps with React Native. Microsoft created it in 2012, and today a good part of the web industry uses it. Prodigia is written in TypeScript.","The advantage in a team: the editor autocompletes and flags errors as you type. If someone renames a property, TypeScript points out every place still using the old name:\n```typescript!\ninterface Usuario {\n  nombreCompleto: string;\n}\nconst u: Usuario = { nombreCompleto: \"Ana Paz\" };\nconsole.log(u.nombre);\n```\n```salida\ncompilation error\n```\nIn a project with thousands of files, that prevents a huge number of errors.","A realistic example: describing the data of a game and calculating the accuracy.\n```typescript\ninterface Partida {\n  mundo: string;\n  correctas: number;\n  total: number;\n}\nfunction precision(p: Partida): string {\n  return Math.round((p.correctas / p.total) * 100) + \"%\";\n}\nconst partida: Partida = { mundo: \"Codia\", correctas: 8, total: 10 };\nconsole.log(precision(partida));\n```\n```salida\n80%\n```","Generics let you write a function that works for any type without losing which one it is: T is \"whatever the type is\".\n```typescript\nfunction primero<T>(lista: T[]): T {\n  return lista[0];\n}\nconst n = primero([4, 5, 6]);\nconst s = primero([\"a\", \"b\"]);\nconsole.log(n + 1, s.toUpperCase());\n```\n```salida\n5 A\n```","The cost: you have to compile and write types. Rule of thumb: for a small script or a one-person project, JavaScript is enough; for a big project or one built by a team, TypeScript pays for itself."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What does it print?\n```typescript\nfunction total(xs: number[]): number {\n  return xs.reduce((a, b) => a + b, 0);\n}\nconsole.log(total([1, 2, 3]));\n```","opciones":["6","123","3"],"respuesta":"6","explicacion":"reduce adds up the list: 1 + 2 + 3 = 6."},{"pregunta":"Who created TypeScript?","opciones":["Google","Microsoft","Oracle"],"respuesta":"Microsoft","explicacion":"Microsoft introduced it in 2012."},{"pregunta":"When is TypeScript a better fit than JavaScript?","opciones":["In a ten-line script","In big projects or ones built by a team","Never: they're the same"],"respuesta":"In big projects or ones built by a team","explicacion":"Types help many people change the code without breaking it."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":0,"titulo":"TypeScript in the real world","cuadros":[{"texto":"Big pages with React or Angular"},{"texto":"Servers with Node.js"},{"texto":"Apps with React Native"},{"texto":"Big teams: the editor flags the errors"}]}]$leccion_en$::jsonb
    )
where slug = 'codia-clase-typescript-3-usos';
